query FindPathsBetweenNodes($sourceNodeId: ID!, $targetNodeId: ID!, $maxDepth: Int = 3, $relationTypeIds: [ID!]) {
  findPathsBetweenNodes(
    input: {
      sourceNodeId: $sourceNodeId
      targetNodeId: $targetNodeId
      maxDepth: $maxDepth
      relationTypeIds: $relationTypeIds
    }
  ) {
    nodes {
      id
      content
      table {
        id
        identifier
      }
    }
    relations {
      id
      relationType {
        identifier
        name
      }
      sourceNode {
        id
        content
      }
      targetNode {
        id
        content
      }
    }
    length
    totalWeight
  }
}
